local menuid = 3
-- 1: objects collision
-- 2: geograph
-- 3: tiles collision

local collisionAutoMove = false
local collisionHitboxBoard = false

local geographDistance = false

-----------------------------------------
-----------------------------------------
-----------------------------------------

local cursor = {}

local function setCommonObjFields(obj, div)
	div = div or 10

	obj.x  =  math.random(2, 238)
	obj.y  =  math.random(2, 134)
	obj.sx = (math.random(5,  10) / div) * (math.random(2) == 1 and -1 or 1)
	obj.sy = (math.random(5,  10) / div) * (math.random(2) == 1 and -1 or 1)

	function obj:automove()
		self.x = self.x + self.sx
		self.y = self.y + self.sy

		if self.x <= 1 or self.x >= 239 then self.sx = self.sx * -1 end
		if self.y <= 1 or self.y >= 135 then self.sy = self.sy * -1 end
	end
end

-----------------------------------------

local collision = {}

local function updateCollisionTests()
	-- this is too slow
	for i, objA in ipairs(collision)
	do
		if collisionAutoMove
		then
			objA:automove()
		else
			objA:cursormove()
		end

		for j, objB in ipairs(collision)
		do
			if i ~= j
			then
				if objB.w
				then
					objA:crect(objB)
				elseif objB.r
				then
					objA:ccirc(objB)
				else
					objA:cpix(objB)
				end
			end
		end
	end
end

local function drawCollisionTests()
	if not collisionAutoMove
	then
		print("Click on an object to move it.", 2, 123, 15)
		print("It is \"hard\", or even impossible, move them.", 2, 129, 15, false, 1, true)
	end

	for i, v in ipairs(collision)
	do
		v:draw()
	end

	drawHitboxes()
end

local function createCollisionTests()
	local availableColors = {3, 4, 5, 11, 12}
	local debug = {enableDebug = true, board = collisionHitboxBoard}

	collision[1] = newRect(0, 0, math.random(5, 20), debug)
	collision[2] = newRect(0, 0, math.random(5, 20), math.random(5, 20), debug)
	collision[3] = newRect(0, 0, 1, math.random(5, 20), debug)
	collision[4] = newRect(0, 0, math.random(5, 20), 1, debug)
	collision[5] = newCirc(0, 0, math.random(3, 10), debug)
	collision[6] = newCirc(0, 0, math.random(3, 10), debug)
	collision[7] = newPix( 0, 0, debug)

	for i, v in ipairs(collision)
	do
		setCommonObjFields(v)
		setColiMethods(v, true)

		function v:cursormove()
			if cursor.pressed and self:cpix(cursor)
			then
				self.x = cursor.x - (self.w and self.w // 2 or 0)
				self.y = cursor.y - (self.w and self.h // 2 or 0)
			end
		end

		if v.w
		then
			function v:draw()
				rect(self.x, self.y, self.w, self.h, 6)
			end
		elseif v.r
		then
			function v:draw()
				circ(self.x, self.y, self.r, 6)
			end
		else
			function v:draw()
				pix(self.x, self.y, 6)
			end
		end
	end
end

-----------------------------------------

local geograph, gpoint = {}, newPix(120, 68)
local gdebug = {enableDebug = true, color = 7}
local gdistance

local function updateGeographTests()
	if geographDistance
	then
		gdistance = distance(cursor, gpoint)
		return
	end

	for _, v in ipairs(geograph)
	do
		v:automove()
		getMapGridPosition(v, v.w and not v.r, math.ceil(v.w and v.w / 8 or 0), math.ceil(v.w and v.h / 8 or 0), gdebug)
	end
end

local function drawGeographTests()
	if geographDistance
	then
		pix(gpoint.x, gpoint.y, 4)

		local list = {
			"Point     [ X:" .. gpoint.x .. ", Y: " .. gpoint.y .. " ]",
			"Cursor    [ X:" .. cursor.x .. ", Y: " .. cursor.y .. " ]",
			"Distance: [ " .. gdistance .. " ]"
		}

		for i = 1, #list
		do
			print(list[i], 125, 64 + 8 * (i - 1), i + 1, true, 1, true)
		end

		return
	end

	map()

	for i, v in ipairs(geograph)
	do
		v:draw()
		v:drawMapGridPos()
	end
end

local function createGeographTests()
	local max, obj = math.random(5, 8)

	for i = 1, max
	do
		if math.random(2) == 1
		then
			obj = newRect(0, 0, math.random(5) * 8, math.random(5) * 8)

			function obj:draw()
				rect( self.x, self.y, self.w, self.h, 6)
				rectb(self.x, self.y, self.w, self.h, 5)
			end
		else
			obj = newCirc(0, 0, math.random(5) * 2)

			function obj:draw()
				circ( self.x, self.y, self.r, 6)
				circb(self.x, self.y, self.r, 5)
			end
		end

		setCommonObjFields(obj, 40)
		table.insert(geograph, obj)
	end
end

-----------------------------------------

local tilecollision, keymap = {}, {}
setMapPos(30)

local function updateTileCollisionTests()
	keymap[0] = key(23) -- w : top
	keymap[2] = key( 1) -- a : left
	keymap[1] = key(19) -- s : bottom
	keymap[3] = key( 4) -- d : right

	for i, v in ipairs(tilecollision)
	do
		v:btnmove()
	end
end

local function drawTileCollisionTests()
	map(getMapPos())

	for i, v in ipairs(tilecollision)
	do
		v:draw()
	end

	drawTilePoints()

	rect(1, 1, 65, 6, 0)
	print("Keys pressed:", 2, 1, 3, false, 1, true)
	for i = 0, #keymap
	do
		print(keymap[i] and 1 or 0, 50 + i * 4, 1, keymap[i] and 2 or 1, false, 1, true)
	end
end

local function createTileCollisionTests()
	local obj
	local debug = {enableDebug = true, board = true}
	local body = {
		{8,     8,  4},
		{8,   120,  8},
		{80,   40, 24},
		{140, 110,  3, 15},
		{180,  50, 17,  5},
	}

	for i = 1, #body
	do
		obj = newRect( table.unpack(body[i]) )
		setTilesCollision(obj, 0, nil, debug)
		obj.s = 1

		function obj:btnmove()
			-- this code depends of the maximum
			-- number of keys that your keyboard
			-- allows that they are pressed
			-- simultaneously;
			-- this algorithm prefers to walk
			-- in column, instead row, because
			-- only the "row conditions" check
			-- the object corners
			local btop    = keymap[0]
			local bbottom = keymap[1]
			local bleft   = keymap[2]
			local bright  = keymap[3]

			if btop and bbottom and bleft and bright
			then
				return
			end

			local isBlocked

			if btop
			then
				isBlocked = bbottom or self.tcol:top()
				if not isBlocked then self.y = self.y - self.s end

				if bleft
				then
					if not bright and not self.tcol:left() and (isBlocked or not self.tcol:cornertl())
					then
						self.x = self.x - self.s
					end

				elseif bright and not self.tcol:right() and (isBlocked or not self.tcol:cornertr())
				then
					self.x = self.x + self.s
				end

			elseif bbottom
			then
				isBlocked = self.tcol:bottom()
				if not isBlocked then self.y = self.y + self.s end

				if bleft
				then
					if not bright and not self.tcol:left() and (isBlocked or not self.tcol:cornerbl())
					then
						self.x = self.x - self.s
					end

				elseif bright and not self.tcol:right() and (isBlocked or not self.tcol:cornerbr())
				then
					self.x = self.x + self.s
				end

			elseif bleft
			then
				if not bright and not self.tcol:left() then self.x = self.x - self.s end

			elseif bright and not self.tcol:right()
			then
				self.x = self.x + self.s

			end

			self.tcol:setxy()
		end

		function obj:draw()
			rect( self.x, self.y, self.w, self.h, 8)
			rectb(self.x, self.y, self.w, self.h, 9)
		end

		tilecollision[i] = obj
	end
end

-----------------------------------------

function BOOT()
	createCollisionTests()
	createGeographTests()
	createTileCollisionTests()
end

function TIC()
	cls()
	cursor.x, cursor.y, cursor.pressed = mouse()
	poke(0x03FF8, 15)
	poke(0x03FFB, 0)

	if menuid == 0
	then
		print("Edit the \"MENU\".", 2, 2, 15)
		print("(in the cartridge code).", 2, 8, 15, false, 1, true)
	elseif menuid == 1
	then
		updateCollisionTests()
		drawCollisionTests()
	elseif menuid == 2
	then
		updateGeographTests()
		drawGeographTests()
	elseif menuid == 3
	then
		updateTileCollisionTests()
		drawTileCollisionTests()
	end

	rectb(0, 0, 240, 136, 14)
	spr(3, cursor.x - 3, cursor.y - 3, 15)
end

